const { nodeDefinitions } = require('../definitions/node')

const createDefinitionsRegistry = (initialDefs = {}) => {
  const definitions = new Map()

  const registerDefinition = (def) => {
    if (!def || !def.type || !def.version) {
      throw new Error('Event definition must specify "type" and "version"')
    }
    const key = `${def.type}@${def.version}`
    definitions.set(key, def)
  }

  // Register system node definitions
  nodeDefinitions.forEach(registerDefinition)
  if (initialDefs) {
    if (Array.isArray(initialDefs)) {
      initialDefs.forEach(registerDefinition)
    } else if (typeof initialDefs === 'object') {
      Object.entries(initialDefs).forEach(([key, val]) => {
        if (val && val.type && val.version) {
          registerDefinition(val)
        } else if (val && typeof val === 'object') {
          const parts = key.split('@')
          const type = parts[0]
          const version = parts[1] || '1.0.0'
          registerDefinition({
            type,
            version,
            ...val,
          })
        }
      })
    }
  }

  const getDefinition = (type, version) => {
    return definitions.get(`${type}@${version}`) || null
  }

  const validatePayload = async (type, version, payload) => {
    const def = getDefinition(type, version)
    if (def && typeof def.validate === 'function') {
      await def.validate(payload)
    }
    return true
  }

  const getDeduplicationId = (type, version, payload) => {
    const def = getDefinition(type, version)
    if (def && typeof def.deduplicationId === 'function') {
      return def.deduplicationId(payload)
    }
    if (payload && payload.deduplicationId) return String(payload.deduplicationId)
    return null
  }

  const getPartitionKey = (type, version, payload) => {
    const def = getDefinition(type, version)
    if (def && typeof def.partitionKey === 'function') {
      return def.partitionKey(payload)
    }
    if (payload && payload.id) return `${type}#${payload.id}`
    return `${type}#default`
  }

  return {
    registerDefinition,
    getDefinition,
    validatePayload,
    getDeduplicationId,
    getPartitionKey,
    rawDefinitions: () => Object.fromEntries(definitions.entries()),
  }
}

module.exports = {
  createDefinitionsRegistry,
}
